import { MakeLogicType, actions, connect, kea, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import api, { ApiError } from 'lib/api'
import { lemonToast } from 'lib/lemon-ui/LemonToast'
import { teamLogic } from 'scenes/teamLogic'

import { evaluationErrorMessage } from './evaluations/apiErrors'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface llmEvaluationExecutionLogicValues {
    currentTeamId: number | null // teamLogic
    evaluationRun: {
        workflow_id: string
    } | null
    evaluationRunLoading: boolean
    lastRunWorkflowId: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface llmEvaluationExecutionLogicActions {
    runEvaluation: (
        evaluationId: string,
        targetEventId: string,
        timestamp: string,
        event: string,
        distinctId?: string
    ) => {
        distinctId: string | undefined
        evaluationId: string
        event: string
        targetEventId: string
        timestamp: string
    }
    runEvaluationFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    runEvaluationSuccess: (
        evaluationRun: {
            evaluation: {
                id: string
                name: string
            }
            status: string
            target_event_id: string
            workflow_id: string
        } | null,
        payload?: {
            distinctId: string | undefined
            evaluationId: string
            event: string
            targetEventId: string
            timestamp: string
        }
    ) => {
        evaluationRun: {
            evaluation: {
                id: string
                name: string
            }
            status: string
            target_event_id: string
            workflow_id: string
        } | null
        payload?: {
            distinctId: string | undefined
            evaluationId: string
            event: string
            targetEventId: string
            timestamp: string
        }
    }
}

export type llmEvaluationExecutionLogicType = MakeLogicType<
    llmEvaluationExecutionLogicValues,
    llmEvaluationExecutionLogicActions
>

export const llmEvaluationExecutionLogic = kea<llmEvaluationExecutionLogicType>([
    path(['products', 'ai_observability', 'frontend', 'llmEvaluationExecutionLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
    })),
    actions({
        runEvaluation: (
            evaluationId: string,
            targetEventId: string,
            timestamp: string,
            event: string,
            distinctId?: string
        ) => ({
            evaluationId,
            targetEventId,
            timestamp,
            event,
            distinctId,
        }),
    }),
    loaders(({ values }) => ({
        // A null value means the run was rejected, not that one is pending: the loader swallows a
        // client error so it does not reach error tracking. Anything reacting to
        // `runEvaluationSuccess`, `evaluationRun`, or `lastRunWorkflowId` must treat null as "no
        // run started" — a listener that assumes success gets rejections too.
        evaluationRun: [
            null as { workflow_id: string } | null,
            {
                runEvaluation: async ({ evaluationId, targetEventId, timestamp, event, distinctId }) => {
                    if (!values.currentTeamId) {
                        throw new Error('No team selected')
                    }

                    try {
                        const payload: {
                            evaluation_id: string
                            target_event_id: string
                            timestamp: string
                            event: string
                            distinct_id?: string
                        } = {
                            evaluation_id: evaluationId,
                            target_event_id: targetEventId,
                            timestamp: timestamp,
                            event: event,
                        }

                        if (distinctId) {
                            payload.distinct_id = distinctId
                        }

                        const response = await api.evaluationRuns.create(payload)

                        lemonToast.success('Evaluation started successfully')
                        return response
                    } catch (error) {
                        const status = error instanceof ApiError ? error.status : undefined
                        // The backend turns some runs down on purpose, because a trace- or
                        // session-target evaluation cannot be re-run against one generation. That
                        // answer explains itself to the user, and it is not a defect, so it must
                        // not reach error tracking as an unhandled exception.
                        if (status !== undefined && status < 500) {
                            lemonToast.error(evaluationErrorMessage(error, 'Failed to start evaluation'))
                            return null
                        }
                        // A fault gets the generic text, because its body is an internal message
                        // rather than something the user can act on. It keeps throwing so that
                        // error tracking still receives it. `api.ts` leaves the status unset when
                        // the request never reached the backend, or when the response body could
                        // not be read, and there the run may already have started.
                        lemonToast.error('Failed to start evaluation')
                        throw error
                    }
                },
            },
        ],
    })),
    reducers({
        lastRunWorkflowId: [
            null as string | null,
            {
                runEvaluationSuccess: (_, { evaluationRun }) => evaluationRun?.workflow_id || null,
            },
        ],
    }),
])
